begin;

-- Shared, atomic abuse budgets for serverless monitoring endpoints. Keys are
-- opaque HMACs generated by the backend; only the service role can access them.
create table public.service_rate_limits (
  key_hash text primary key check (key_hash ~ '^[0-9a-f]{64}$'),
  request_count integer not null check (request_count > 0),
  reset_at timestamptz not null,
  updated_at timestamptz not null default now()
);

alter table public.service_rate_limits enable row level security;
revoke all on table public.service_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on table public.service_rate_limits to service_role;

create or replace function public.consume_service_rate_limit(
  p_key_hash text,
  p_limit integer,
  p_window_seconds integer
) returns table (
  allowed boolean,
  remaining integer,
  retry_after integer
)
language plpgsql
security invoker
set search_path = ''
as $$
declare
  current_count integer;
  current_reset timestamptz;
  v_now timestamptz := clock_timestamp();
begin
  if p_key_hash !~ '^[0-9a-f]{64}$'
     or p_limit not between 1 and 100
     or p_window_seconds not between 60 and 86400 then
    raise exception 'Invalid rate-limit request';
  end if;

  delete from public.service_rate_limits
  where reset_at < v_now - interval '1 day';

  insert into public.service_rate_limits (key_hash, request_count, reset_at, updated_at)
  values (p_key_hash, 1, v_now + make_interval(secs => p_window_seconds), v_now)
  on conflict (key_hash) do update
  set request_count = case
        when public.service_rate_limits.reset_at <= v_now then 1
        else public.service_rate_limits.request_count + 1
      end,
      reset_at = case
        when public.service_rate_limits.reset_at <= v_now
          then v_now + make_interval(secs => p_window_seconds)
        else public.service_rate_limits.reset_at
      end,
      updated_at = v_now
  returning request_count, reset_at into current_count, current_reset;

  return query select
    current_count <= p_limit,
    greatest(0, p_limit - current_count),
    case when current_count <= p_limit then 0
      else greatest(1, ceil(extract(epoch from (current_reset - v_now)))::integer)
    end;
end;
$$;

revoke all on function public.consume_service_rate_limit(text, integer, integer)
from public, anon, authenticated;
grant execute on function public.consume_service_rate_limit(text, integer, integer)
to service_role;

-- Service-role portal writes carry the already-authenticated application actor
-- in a server-only request header. Preserve that actor in the mandatory audit
-- entry and reject forged/inactive actor identifiers.
create or replace function private.audit_business_mutation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  row_data jsonb;
  request_headers jsonb := coalesce(nullif(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb);
  raw_actor text := request_headers ->> 'x-ns-actor-id';
  actor uuid := auth.uid();
  raw_id text;
  row_id uuid;
  row_number text;
begin
  if actor is null and raw_actor is not null then
    if raw_actor !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'Invalid audit actor';
    end if;
    actor := raw_actor::uuid;
    if not exists (
      select 1 from public.profiles
      where id = actor and is_active = true
    ) then
      raise exception 'Inactive audit actor';
    end if;
  end if;

  row_data := case when TG_OP = 'DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end;
  raw_id := nullif(row_data ->> 'id', '');
  row_id := case
    when raw_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then raw_id::uuid
    else null
  end;
  row_number := coalesce(
    row_data ->> 'quotation_number',
    row_data ->> 'invoice_number',
    row_data ->> 'receipt_number',
    row_data ->> 'cost_number',
    row_data ->> 'customer_code',
    row_data ->> 'worker_code',
    row_data ->> 'project_code',
    row_data ->> 'public_reference',
    row_data ->> 'name'
  );

  insert into public.audit_logs (
    actor_id, action, module, record_id, record_number, new_value
  ) values (
    actor, lower(TG_OP), TG_TABLE_NAME, row_id, row_number,
    jsonb_build_object('source', 'database_trigger')
  );

  return case when TG_OP = 'DELETE' then OLD else NEW end;
end;
$$;

revoke all on function private.audit_business_mutation() from public, anon, authenticated;

-- Replace all fields and line items for a draft under one row lock. This is the
-- sole authenticated quotation-edit mutation after the enforcement migration.
create or replace function public.replace_draft_quotation(
  p_quotation_id uuid,
  p_customer_id uuid,
  p_quotation_date date,
  p_expiry_date date,
  p_project_title text,
  p_project_location text,
  p_description text,
  p_discount_amount numeric,
  p_tax_percent numeric,
  p_other_charges numeric,
  p_notes text,
  p_terms_and_conditions text,
  p_items jsonb
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  target public.quotations%rowtype;
  customer public.customers%rowtype;
  item jsonb;
  item_description text;
  item_quantity numeric;
  item_unit_price numeric;
  item_position integer := 0;
  calculated_subtotal numeric(14,2);
  updated_quotation public.quotations%rowtype;
begin
  if actor is null or not public.is_authorized_staff() then
    raise exception 'Active staff access is required';
  end if;

  select * into target
  from public.quotations
  where id = p_quotation_id
  for update;

  if not found then raise exception 'Quotation was not found'; end if;
  if target.status <> 'draft' or target.sent_at is not null or target.approved_at is not null then
    raise exception 'Only an unreserved draft quotation can be edited';
  end if;

  select * into customer
  from public.customers
  where id = p_customer_id and is_active = true;

  if not found then raise exception 'Customer was not found'; end if;
  if p_expiry_date < p_quotation_date
     or char_length(trim(coalesce(p_project_title, ''))) not between 2 and 200
     or char_length(coalesce(p_project_location, '')) > 500
     or char_length(coalesce(p_description, '')) > 2000
     or char_length(coalesce(p_notes, '')) > 2000
     or char_length(coalesce(p_terms_and_conditions, '')) > 5000
     or p_discount_amount is null or p_discount_amount < 0 or p_discount_amount::text = 'NaN'
     or p_tax_percent is null or p_tax_percent < 0 or p_tax_percent > 100 or p_tax_percent::text = 'NaN'
     or p_other_charges is null or p_other_charges < 0 or p_other_charges::text = 'NaN'
     or coalesce(jsonb_typeof(p_items), 'null') <> 'array' then
    raise exception 'Invalid quotation details';
  end if;
  if jsonb_array_length(p_items) not between 1 and 50 then
    raise exception 'Invalid quotation details';
  end if;

  -- Neutral values keep the existing discount/subtotal constraint valid while
  -- the old lines are replaced and total-refresh triggers run.
  update public.quotations
  set discount_amount = 0, tax_percent = 0, other_charges = 0
  where id = target.id;

  delete from public.quotation_items where quotation_id = target.id;

  for item in select value from jsonb_array_elements(p_items)
  loop
    item_position := item_position + 1;
    item_description := trim(coalesce(item ->> 'description', ''));
    begin
      item_quantity := (item ->> 'quantity')::numeric;
      item_unit_price := (item ->> 'unit_price')::numeric;
    exception when others then
      raise exception 'Invalid quotation item';
    end;

    if char_length(item_description) not between 1 and 500
       or item_quantity <= 0 or item_quantity::text = 'NaN'
       or item_unit_price < 0 or item_unit_price::text = 'NaN' then
      raise exception 'Invalid quotation item';
    end if;

    insert into public.quotation_items (
      quotation_id, position, description, quantity, unit_price
    ) values (
      target.id, item_position, item_description, item_quantity, item_unit_price
    );
  end loop;

  select coalesce(sum(line_total), 0)
  into calculated_subtotal
  from public.quotation_items
  where quotation_id = target.id;

  if p_discount_amount > calculated_subtotal then
    raise exception 'Discount cannot exceed subtotal';
  end if;

  update public.quotations
  set customer_id = customer.id,
      quotation_date = p_quotation_date,
      expiry_date = p_expiry_date,
      project_title = trim(p_project_title),
      project_location = nullif(trim(p_project_location), ''),
      description = nullif(trim(p_description), ''),
      customer_snapshot = jsonb_build_object(
        'id', customer.id,
        'customer_code', customer.customer_code,
        'customer_type', customer.customer_type,
        'name', customer.name,
        'company_registration_number', customer.company_registration_number,
        'phone', customer.phone,
        'email', customer.email,
        'contact_person', customer.contact_person,
        'billing_address', customer.billing_address,
        'service_address', customer.service_address
      ),
      discount_amount = p_discount_amount,
      tax_percent = p_tax_percent,
      other_charges = p_other_charges,
      notes = nullif(trim(p_notes), ''),
      terms_and_conditions = nullif(trim(p_terms_and_conditions), '')
  where id = target.id
  returning * into updated_quotation;

  return to_jsonb(updated_quotation);
end;
$$;

revoke all on function public.replace_draft_quotation(
  uuid, uuid, date, date, text, text, text, numeric, numeric, numeric, text, text, jsonb
) from public, anon;
grant execute on function public.replace_draft_quotation(
  uuid, uuid, date, date, text, text, text, numeric, numeric, numeric, text, text, jsonb
) to authenticated;

-- Remove the obsolete overload and make storage-object existence an atomic
-- database invariant for the current cash-account-aware payment function.
drop function if exists public.record_invoice_payment(
  uuid, date, numeric, public.payment_method, text, text, text
);

create or replace function public.record_invoice_payment(
  p_invoice_id uuid,
  p_payment_date date,
  p_amount numeric,
  p_payment_method public.payment_method,
  p_transaction_reference text,
  p_notes text,
  p_proof_storage_path text,
  p_cash_account_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  target public.invoices%rowtype;
  payment_row public.payments%rowtype;
  receipt_row public.receipts%rowtype;
  receipt_no text;
begin
  if actor is null or not public.is_authorized_staff() then
    raise exception 'Active staff access is required';
  end if;

  select * into target
  from public.invoices
  where id = p_invoice_id and archived_at is null
  for update;

  if not found or target.status not in ('unpaid','partially_paid','overdue') then
    raise exception 'Select an issued invoice with an outstanding balance';
  end if;
  if p_amount <= 0 or p_amount > target.balance or p_amount::text = 'NaN' then
    raise exception 'Invalid payment amount';
  end if;
  if not exists (
    select 1 from public.cash_accounts
    where id = p_cash_account_id and is_active
  ) then
    raise exception 'Select an active cash account';
  end if;
  if p_proof_storage_path is null
     or p_proof_storage_path not like target.id::text || '/%'
     or not exists (
       select 1 from storage.objects
       where bucket_id = 'payment-proofs'
         and name = p_proof_storage_path
     ) then
    raise exception 'Verified payment proof is required';
  end if;

  insert into public.payments (
    invoice_id, customer_id, cash_account_id, payment_date, amount, payment_method,
    transaction_reference, notes, proof_storage_path, recorded_by
  ) values (
    target.id, target.customer_id, p_cash_account_id, p_payment_date, p_amount,
    p_payment_method, nullif(trim(p_transaction_reference), ''),
    nullif(trim(p_notes), ''), p_proof_storage_path, actor
  ) returning * into payment_row;

  receipt_no := public.next_document_number('receipt', p_payment_date);
  insert into public.receipts (
    receipt_number, payment_id, invoice_id, customer_id, amount_received,
    remaining_balance, prepared_by
  ) values (
    receipt_no, payment_row.id, target.id, target.customer_id, p_amount,
    target.balance - p_amount, actor
  ) returning * into receipt_row;

  return jsonb_build_object(
    'payment', to_jsonb(payment_row),
    'receipt', to_jsonb(receipt_row)
  );
end;
$$;

revoke all on function public.record_invoice_payment(
  uuid, date, numeric, public.payment_method, text, text, text, uuid
) from public, anon;
grant execute on function public.record_invoice_payment(
  uuid, date, numeric, public.payment_method, text, text, text, uuid
) to authenticated;

commit;
